property.value:
(: factory method call :)
//PostfixUnaryExpression[pmd-kotlin:matchesSig('javax.xml.datatype.DatatypeFactory#newXMLGregorianCalendar(*)')]
|
(: property/field with XMLGregorianCalendar declared type (name-based: distinctive class name) :)
//PropertyDeclaration[
    (: isWithin pattern :)
    not(ancestor::FunctionBody or ancestor::LambdaLiteral)
    and .//T-Identifier[@Text='XMLGregorianCalendar']
]
|
(: function parameter typed as XMLGregorianCalendar :)
//FunctionValueParameter[.//T-Identifier[@Text='XMLGregorianCalendar']]

rule.example:
import javax.xml.datatype.XMLGregorianCalendar
import java.time.LocalDateTime

class Foo {
    private var cal: XMLGregorianCalendar? = null // bad
    fun good(dt: LocalDateTime): String = dt.toString() // good
}

property.value:
(: requires type info: kotlin-type-mapper auxClasspath :)
//PropertyDeclaration[
    (: isWithin pattern :)
    not(ancestor::FunctionBody or ancestor::LambdaLiteral)
    and (
        pmd-kotlin:typeIs('com.fasterxml.jackson.databind.ObjectMapper')
        or Expression//PrimaryExpression[
            pmd-kotlin:typeIs('com.fasterxml.jackson.databind.ObjectMapper')
        ]
    )
]

rule.example:
import com.fasterxml.jackson.databind.ObjectMapper
import com.fasterxml.jackson.databind.ObjectReader

class Foo {
    private val mapper: ObjectMapper = ObjectMapper() // bad
    private val reader: ObjectReader = ObjectMapper().readerFor(Any::class.java) // good
}

import com.fasterxml.jackson.databind.ObjectMapper

class Foo {
    companion object {
        private val MAPPER = ObjectMapper() // good
    }
    fun toJson(obj: Any): String {
        return ObjectMapper().writeValueAsString(obj) // bad
    }
}

