import org.springframework.http.client.BufferingClientHttpRequestFactory
import org.springframework.http.client.ClientHttpRequestFactory

class Bad(delegate: ClientHttpRequestFactory) {
    val factory = BufferingClientHttpRequestFactory(delegate) // bad
}


import org.apache.http.HttpHost

class Bad {
    val host = HttpHost("hostname") // bad: no port specified
}

class Good {
    val host = HttpHost("hostname", 443, "https") // ok
}


import javax.xml.bind.JAXB
import javax.xml.transform.Source

class Bad {
    fun <T> unmarshal(src: Source, clazz: Class<T>): T = JAXB.unmarshal(src, clazz) // bad
}


import javax.xml.bind.JAXBContext

class Bad {
    fun marshal(obj: Any): String {
        val ctx = JAXBContext.newInstance(obj::class.java) // bad: recreated per call
        return ctx.createMarshaller().run { java.io.StringWriter().also { marshal(obj, it) }.toString() }
    }
}
class Good {
    companion object {
        private val CTX = JAXBContext.newInstance(Good::class.java) // ok: created once
    }
}


import reactor.core.publisher.Hooks

class AppConfig {
    init {
        Hooks.onOperatorDebug() // bad: heavy overhead in production
    }
}


import org.apache.http.impl.client.HttpClients

class Bad {
    fun doRequest(url: String) =
        HttpClients.custom().build() // bad: recreated per call
            .execute(org.apache.http.client.methods.HttpGet(url))
}
class Good {
    companion object {
        private val HTTP_CLIENT = HttpClients.custom().build() // ok: created once
    }
}

property.value:
//PostfixUnaryExpression[
    pmd-kotlin:matchesSig('io.github.resilience4j.retry.Retry#getEventPublisher(*)')
    and (: isWithin pattern :)
    ancestor::FunctionBody
    and PrimaryExpression/SimpleIdentifier/T-Identifier/@Text =
        ancestor::ClassBody[1]//PropertyDeclaration[
            (: isWithin pattern :)
            not(ancestor::FunctionBody or ancestor::LambdaLiteral)
        ]/VariableDeclaration/@Identifier
]

rule.example:

import io.github.resilience4j.retry.Retry
import io.github.resilience4j.retry.RetryRegistry
import java.util.concurrent.atomic.AtomicInteger
class Service(registry: RetryRegistry) {
    private val retryField: Retry = registry.retry("svc")
    private val count = AtomicInteger()
    init {
        retryField.getEventPublisher().onRetry { count.getAndIncrement() } // ok: registered once
    }
    fun callService() { // avoid: retryField.getEventPublisher().onRetry { ... } here
        retryField.executeCallable { "result" }
    }
}

