rule.example:
import feign.Client
class MyFeignClient {
    fun bad(socketFactory: javax.net.ssl.SSLSocketFactory, hostnameVerifier: javax.net.ssl.HostnameVerifier): Client {
        return Client.Default(socketFactory, hostnameVerifier) // bad
    }
    fun good(): Client {
        return Client.Default(null, null) // good
    }
}

class BadConnectionConfig {
    private val connectionTimeout: Int = 5000 // bad
}
class GoodConnectionConfig {
    @org.springframework.beans.factory.annotation.Value("\${app.timeout}")
    private val connectionTimeout: Int = 0 // good
}

