    ValueArguments/ValueArgument/Expression//T-IntegerLiteral[number(@Text) > 500]
    and parent::PostfixUnarySuffix/preceding-sibling::PostfixUnarySuffix[1]/NavigationSuffix/SimpleIdentifier/*/@Text = ('setConnectionRequestTimeout', 'setConnectTimeout')
]
|
//PropertyDeclaration[
    (: isWithin pattern :)
    not(ancestor::FunctionBody or ancestor::LambdaLiteral)
    and (pmd-kotlin:typeIs('kotlin.Int') or pmd-kotlin:typeIs('kotlin.Long')
         or pmd-kotlin:typeIs('java.lang.Integer') or pmd-kotlin:typeIs('java.lang.Long'))
    and Expression//T-IntegerLiteral[number(@Text) > 500]
    and VariableDeclaration/@Identifier = ancestor::ClassDeclaration[1]//CallSuffix[
        parent::PostfixUnarySuffix/preceding-sibling::PostfixUnarySuffix[1]/NavigationSuffix/SimpleIdentifier/*/@Text = ('setConnectionRequestTimeout', 'setConnectTimeout')
    ]/ValueArguments/ValueArgument/Expression//PrimaryExpression/SimpleIdentifier/*/@Text
]

