rule.example:
fun bad(poolMgr: PoolingHttpClientConnectionManager) {
    HttpClientBuilder.create()
        .setConnectionManager(poolMgr)
        .setMaxConnTotal(200) // bad, ignored
        .build()
}

fun good(poolMgr: PoolingHttpClientConnectionManager) {
    HttpClientBuilder.create()
        .setConnectionManager(poolMgr)
        .build()
}

