property.value:
//IfExpression[
    ancestor::FunctionDeclaration[@Identifier='intercept']
    and ancestor::FunctionBody[1]//PropertyDeclaration[
        VariableDeclaration/@Identifier='response'
        and (
            Expression//PostfixUnaryExpression[pmd-kotlin:matchesSig('org.springframework.http.client.ClientHttpRequestExecution#execute(*)')]
            or Expression//NavigationSuffix/SimpleIdentifier/*/@Text='execute'
        )
    ]
    and .//SimpleIdentifier/T-Identifier[@Text='response']
    and .//*[@Text='throw']
    and not(.//PostfixUnaryExpression[
        pmd-kotlin:matchesSig('org.springframework.http.client.ClientHttpResponse#close()')
        or PostfixUnarySuffix/NavigationSuffix/SimpleIdentifier/*/@Text='close'
    ])
    and not(ancestor::FunctionDeclaration[1]//PostfixUnaryExpression[
        PostfixUnarySuffix/NavigationSuffix/SimpleIdentifier/*/@Text='use'
    ])
    and not(ancestor::FunctionDeclaration[1]//CatchBlock//PostfixUnaryExpression[
        pmd-kotlin:matchesSig('org.springframework.http.client.ClientHttpResponse#close()')
        or PostfixUnarySuffix/NavigationSuffix/SimpleIdentifier/*/@Text='close'
    ])
]

rule.example:
class BadInterceptor : org.springframework.http.client.ClientHttpRequestInterceptor {
    override fun intercept(
        request: org.springframework.http.HttpRequest,
        body: ByteArray,
        execution: org.springframework.http.client.ClientHttpRequestExecution
    ): org.springframework.http.client.ClientHttpResponse {
        val response = execution.execute(request, body)
        if (!response.headers.containsKey("X-Ok")) {
            throw IllegalStateException("missing header") // bad
        }
        return response
    }
}

property.value:
(: Flag ThreadPoolTaskExecutor creations in functions that set core/max pool size but omit queue capacity :)
//FunctionDeclaration[
    .//PostfixUnaryExpression[pmd-kotlin:matchesSig('org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor#<init>(*)')]
    and (
        .//NavigationSuffix[SimpleIdentifier/*/@Text=('setCorePoolSize','corePoolSize')]
        or .//NavigationSuffix[SimpleIdentifier/*/@Text=('setMaxPoolSize','maxPoolSize')]
    )
    and not(
        .//NavigationSuffix[SimpleIdentifier/*/@Text=('setQueueCapacity','queueCapacity')]
    )
]/.//PostfixUnaryExpression[pmd-kotlin:matchesSig('org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor#<init>(*)')]

rule.example:
import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor
fun bad(): ThreadPoolTaskExecutor { val executor = ThreadPoolTaskExecutor() executor.setCorePoolSize(10) executor.setMaxPoolSize(20) executor.initialize() return executor // bad: setQueueCapacity missing }
fun good(): ThreadPoolTaskExecutor { val executor = ThreadPoolTaskExecutor() executor.setCorePoolSize(10) executor.setQueueCapacity(10) executor.setMaxPoolSize(20) executor.initialize() return executor }
